const input = ($input.first().json.chatInput || "").trim();

function isUUID(str) {
  // Regex for UUID-like strings (RFC 4122, supports v1–v8)
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  return uuidRegex.test(str);
}

let type = isUUID(input) ? "uuid" : "description";

return [
  {
    json: {
      value: input,
      type: type
    }
  }
];

